SELECT b.Id, b.CharacterProfileId, b.BatchId, b.CurrentStep, b.Status, b.FrontContainerAssetId, b.CanonicalFrontAssetId, b.CreatedUtc, b.UpdatedUtc, s.Step, s.Status AS StepStatus, s.InputArtifactId, s.OutputArtifactId, s.FailureReason, s.ManualOverrideApplied, s.ManualOverrideReason FROM CharacterIdentityBuilds b LEFT JOIN CharacterIdentityBuildSteps s ON s.BuildId = b.Id WHERE b.CharacterProfileId = 'e781811de41f4595af334b06440ea293' ORDER BY b.UpdatedUtc DESC, s.Step;
